using System;using LoopFive;
class RecordingSourceTests {
 static int n;static void A(bool x,string text){if(!x)throw new Exception(text);n++;Console.WriteLine("PASS "+text);}
 static Engine Clean(){Engine e=new Engine();e.Config.InputFx.Enabled=e.Config.TrackFx.Enabled=false;e.Config.Quantize=false;foreach(Track t in e.Tracks){t.Config.Level=1;t.Config.LoopSync=false;}return e;}
 static void Tone(Engine e,int target,float level){float[] l=new float[1024];for(int i=0;i<l.Length;i++)l[i]=level;e.Import(target,new AudioClip(l,(float[])l.Clone(),120,1));e.Play(target);}
 static void Render(Engine e,float mic){float[] a=new float[512],o=new float[512];for(int i=0;i<a.Length;i++)a[i]=mic;e.Process(a,o,256);}
 static void Main(){try{Engine e=Clean();Tone(e,0,.2f);RecordingSource.Set(e,1,1);e.Action(1);Render(e,.9f);A(e.Tracks[1].RecordL.Count==256&&Math.Abs(e.Tracks[1].RecordL[100]-.2f)<.00001,"track 2 records playing track 1 while ignoring microphone input");A(e.Tracks[0].Playing,"source track keeps playing during capture");e.Tracks[0].Config.Mute=true;Render(e,.9f);A(e.Tracks[1].RecordL[300]==0,"new audible-source mode respects source mute");e.Tracks[0].Config.Mute=false;e.Tracks[0].Config.Level=.5f;Render(e,0);A(Math.Abs(e.Tracks[1].RecordL[600]-.1f)<.00001,"source recording follows the source fader level");e.Stop(0,true);Render(e,.8f);A(e.Tracks[1].RecordL[900]==0,"stopped source produces no copied audio");
 e=Clean();Tone(e,0,.2f);Tone(e,2,.3f);RecordingSource.Set(e,1,6);e.Action(1);Render(e,.9f);A(Math.Abs(e.Tracks[1].RecordL[100]-.5f)<.00001&&e.Tracks[1].Config.BounceMask==29,"mix mode captures the other tracks and excludes destination and microphone");e=Clean();Tone(e,0,.2f);RecordingSource.Set(e,1,7);e.Action(1);Render(e,.1f);A(Math.Abs(e.Tracks[1].RecordL[100]-.3f)<.00001,"microphone plus track mix combines both sources");RecordingSource.Set(e,1,0);A(e.Tracks[1].Config.BounceMask==0&&e.Tracks[1].Config.InputL&&e.Tracks[1].Config.InputR,"microphone mode restores direct input without bounce");bool rejected=false;try{RecordingSource.Set(e,1,2);}catch(ArgumentException){rejected=true;}A(rejected,"a track cannot select itself as recording source");TrackConfig c=Storage.Clone(e.Tracks[1].Config);A(c.BounceAudibleOnly&&c.InputL&&c.BounceMask==0,"recording source settings survive session serialization");Console.WriteLine("TOTAL "+n+" recording-source checks passed");}catch(Exception ex){Console.WriteLine("FAIL "+ex);Environment.ExitCode=1;}}
}
